            # add a line below, unless this is the last row or the next row
            # is a separating line (which renders its own horizontal rule)
            if i < len(padded_rows) - 1 and not _is_separating_line(
                padded_rows[i + 1]
            ):
                _append_line(lines, padded_widths, colaligns, fmt.linebetweenrows)
